import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_layer_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename scalar_t, int BLOCK_THREADS>
__global__ void cute_layer_norm_kernel(
    const scalar_t* __restrict__ x_ptr,
    const scalar_t* __restrict__ weight_ptr,
    const scalar_t* __restrict__ bias_ptr,
    scalar_t* __restrict__ out_ptr,
    int rows,
    int cols,
    float eps)
{
    int row = static_cast<int>(blockIdx.x);
    int tid = static_cast<int>(threadIdx.x);

    if (row >= rows) {
        return;
    }

    auto x = make_tensor(
        make_gmem_ptr(x_ptr),
        make_shape(rows, cols),
        make_stride(cols, Int<1>{}));

    auto out = make_tensor(
        make_gmem_ptr(out_ptr),
        make_shape(rows, cols),
        make_stride(cols, Int<1>{}));

    auto weight = make_tensor(
        make_gmem_ptr(weight_ptr),
        make_shape(cols),
        make_stride(Int<1>{}));

    auto bias = make_tensor(
        make_gmem_ptr(bias_ptr),
        make_shape(cols),
        make_stride(Int<1>{}));

    __shared__ float reduction[BLOCK_THREADS];

    float local_sum = 0.0f;
    for (int col = tid; col < cols; col += BLOCK_THREADS) {
        local_sum += static_cast<float>(x(row, col));
    }

    reduction[tid] = local_sum;
    __syncthreads();

    for (int stride = BLOCK_THREADS / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            reduction[tid] += reduction[tid + stride];
        }
        __syncthreads();
    }

    __shared__ float mean_storage;
    if (tid == 0) {
        mean_storage = reduction[0] / static_cast<float>(cols);
    }
    __syncthreads();

    float mean = mean_storage;
    float local_var = 0.0f;

    for (int col = tid; col < cols; col += BLOCK_THREADS) {
        float delta = static_cast<float>(x(row, col)) - mean;
        local_var += delta * delta;
    }

    reduction[tid] = local_var;
    __syncthreads();

    for (int stride = BLOCK_THREADS / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            reduction[tid] += reduction[tid + stride];
        }
        __syncthreads();
    }

    __shared__ float inv_std_storage;
    if (tid == 0) {
        float variance = reduction[0] / static_cast<float>(cols);
        inv_std_storage = rsqrtf(variance + eps);
    }
    __syncthreads();

    float inv_std = inv_std_storage;

    for (int col = tid; col < cols; col += BLOCK_THREADS) {
        float value = (static_cast<float>(x(row, col)) - mean) * inv_std;
        value = value * static_cast<float>(weight(col))
              + static_cast<float>(bias(col));
        out(row, col) = static_cast<scalar_t>(value);
    }
}


torch::Tensor cute_layer_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

    TORCH_CHECK(x.dim() >= 1, "x must have at least one dimension");
    TORCH_CHECK(weight.dim() >= 1, "weight must have at least one dimension");
    TORCH_CHECK(bias.dim() == weight.dim(),
                "bias and weight must have the same number of dimensions");
    TORCH_CHECK(weight.sizes() == bias.sizes(),
                "bias and weight must have the same shape");
    TORCH_CHECK(x.dim() >= weight.dim(),
                "input must have at least as many dimensions as normalized_shape");
    const int64_t normalized_rank = weight.dim();
    const int64_t x_start_dim = x.dim() - normalized_rank;
    for (int64_t i = 0; i < normalized_rank; ++i) {
        TORCH_CHECK(
            x.size(x_start_dim + i) == weight.size(i),
            "input trailing dimensions must match normalized_shape");
    }
    TORCH_CHECK(weight.numel() > 0,
                "normalized_shape must contain at least one element");
    TORCH_CHECK(x.numel() % weight.numel() == 0,
                "input size must be divisible by normalized size");
    TORCH_CHECK(x.scalar_type() == weight.scalar_type(),
                "x and weight must have the same dtype");
    TORCH_CHECK(x.scalar_type() == bias.scalar_type(),
                "x and bias must have the same dtype");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat ||
        x.scalar_type() == at::kHalf ||
        x.scalar_type() == at::kBFloat16,
        "supported dtypes are float32, float16, and bfloat16");

    auto x_contiguous = x.contiguous();
    auto weight_contiguous = weight.contiguous();
    auto bias_contiguous = bias.contiguous();
    auto output = torch::empty_like(x_contiguous);

    int64_t cols64 = weight_contiguous.numel();
    int64_t rows64 = x_contiguous.numel() / cols64;

    TORCH_CHECK(cols64 <= INT_MAX, "normalized dimension is too large");
    TORCH_CHECK(rows64 <= INT_MAX, "number of rows is too large");

    constexpr int BLOCK_THREADS = 256;
    dim3 block(BLOCK_THREADS);
    dim3 grid(static_cast<unsigned int>(rows64));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    AT_DISPATCH_FLOATING_TYPES_AND2(
        at::ScalarType::Half,
        at::ScalarType::BFloat16,
        x_contiguous.scalar_type(),
        "cute_layer_norm",
        [&] {
            cute_layer_norm_kernel<scalar_t, BLOCK_THREADS>
                <<<grid, block, 0, stream>>>(
                    x_contiguous.data_ptr<scalar_t>(),
                    weight_contiguous.data_ptr<scalar_t>(),
                    bias_contiguous.data_ptr<scalar_t>(),
                    output.data_ptr<scalar_t>(),
                    static_cast<int>(rows64),
                    static_cast<int>(cols64),
                    static_cast<float>(eps));
        });

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE layer normalization kernel launch failed");

    return output;
}
"""


cute_ext = load_inline(
    name="cute_layer_norm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_layer_norm"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return cute_ext.cute_layer_norm(
            x,
            self.ln.weight,
            self.ln.bias,
            self.ln.eps,
        )

